# CP26 Step 3A reconstructed metadata merge and age QC.
rm(list=ls()); source(file.path(Sys.getenv("SDY2583_REPO_ROOT",unset="."),"R","shared","reconstructed_panel_framework.R")); rp_install_and_load(c("dplyr","readr","stringr","tibble","purrr")); source(file.path(sd_repo_root(),"R","panels","CP26","MANIFEST_RECONSTRUCTED.R"))
a<-sd_analysis_dir("CP26"); r<-file.path(a,"11_RData"); out<-file.path(a,"04_metadata_merge_age_QC"); dir.create(out,recursive=TRUE,showWarnings=FALSE)
load(file.path(r,"SDY2583_CP26_STEP2_feature_extraction_RECONSTRUCTED.RData")); m<-rp_merge_metadata("CP26",feature_table,CP26_MANIFEST$module_map$feature); analysis_data<-m$data; metadata<-m$metadata
summary<-tibble::tibble(n_rows=nrow(analysis_data),n_valid_age=sum(!is.na(analysis_data$age_for_model)),n_healthy=sum(analysis_data$disease_group=="Healthy control",na.rm=TRUE),n_cancer=sum(analysis_data$disease_group=="Cancer patient",na.rm=TRUE),metadata_source=m$source_file)
readr::write_csv(analysis_data,file.path(out,"SDY2583_CP26_analysis_data_with_metadata_RECONSTRUCTED.csv")); readr::write_csv(summary,file.path(out,"SDY2583_CP26_metadata_age_QC_summary_RECONSTRUCTED.csv")); save(analysis_data,metadata,summary,file=file.path(r,"SDY2583_CP26_STEP3A_metadata_merge_age_QC_RECONSTRUCTED.RData")); print(summary)
